//! A new installation without EXACT (Django): `exact-cli migrate` on an empty database first creates EXACT's own tables from
//! `bootstrap/exact_base_schema.sql` (what Django's `manage.py migrate` creates in an empty database, including its migration
//! records, content types and permissions, so that Django can still be pointed at the database later), then the additive tables
//! as usual. The file is generated by `scripts/make-base-schema.sh` from a fixed EXACT commit; regenerate it when EXACT's models change.

use crate::internal;
use exact_core::{Error, Result};
use sqlx::PgPool;

pub const BASE_SCHEMA: &str = include_str!("../bootstrap/exact_base_schema.sql");

/// The EXACT commit the base schema was generated from (its `-- EXACT commit:` header line).
pub fn base_schema_source() -> &'static str {
    BASE_SCHEMA
        .lines()
        .find_map(|l| l.strip_prefix("-- EXACT commit: "))
        .unwrap_or("unknown")
        .trim()
}

/// No tables at all in the schema `public`: a database just created for this installation.
pub async fn database_is_empty(pool: &PgPool) -> Result<bool> {
    sqlx::query_scalar("SELECT NOT EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public')")
        .fetch_one(pool)
        .await
        .map_err(internal)
}

/// Creates EXACT's tables in one transaction (all or nothing). Only for an empty database: see [`database_is_empty`].
pub async fn apply_base_schema(pool: &PgPool) -> Result<()> {
    let mut tx = pool.begin().await.map_err(internal)?;
    sqlx::raw_sql(BASE_SCHEMA)
        .execute(&mut *tx)
        .await
        .map_err(internal)?;
    tx.commit().await.map_err(internal)
}

/// Creates an active superuser (staff, all permissions) with an already hashed password, plus the preferences row Django's
/// post_save signal would create; with `team`, the user also becomes admin of that team (created when missing). Returns the user id.
pub async fn create_superuser(
    pool: &PgPool,
    username: &str,
    email: &str,
    password_hash: &str,
    team: Option<&str>,
) -> Result<i64> {
    let mut tx = pool.begin().await.map_err(internal)?;
    let id: i64 = sqlx::query_scalar(
        "INSERT INTO users_user (password, last_login, is_superuser, username, first_name, last_name, email, is_staff, is_active, date_joined, points)
         VALUES ($1, NULL, true, $2, '', '', $3, true, true, now(), 0) RETURNING id",
    )
    .bind(password_hash)
    .bind(username)
    .bind(email)
    .fetch_one(&mut *tx)
    .await
    .map_err(|e| match e {
        sqlx::Error::Database(d) if d.is_unique_violation() => {
            Error::Conflict(format!("a user named {username} already exists"))
        }
        other => internal(other),
    })?;
    sqlx::query("INSERT INTO users_userpreferences (user_id, frontend, is_site_admin) VALUES ($1, 2, false)")
        .bind(id)
        .execute(&mut *tx)
        .await
        .map_err(internal)?;
    if let Some(name) = team {
        let team_id: i64 = sqlx::query_scalar(
            "WITH new AS (INSERT INTO users_team (name, website) VALUES ($1, '') ON CONFLICT (name) DO NOTHING RETURNING id)
             SELECT id FROM new UNION ALL SELECT id FROM users_team WHERE name = $1 LIMIT 1",
        )
        .bind(name)
        .fetch_one(&mut *tx)
        .await
        .map_err(internal)?;
        sqlx::query(
            "INSERT INTO users_teammembership (team_id, user_id, is_admin) VALUES ($1, $2, true)",
        )
        .bind(team_id)
        .bind(id)
        .execute(&mut *tx)
        .await
        .map_err(internal)?;
    }
    tx.commit().await.map_err(internal)?;
    Ok(id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn base_schema_is_plain_sql_from_a_known_commit() {
        let commit = base_schema_source();
        assert!(
            commit.len() == 40 && commit.chars().all(|c| c.is_ascii_hexdigit()),
            "header names no EXACT commit: {commit}"
        );
        for line in BASE_SCHEMA.lines() {
            assert!(!line.starts_with('\\'), "psql meta-command left in: {line}");
            assert!(!line.starts_with("COPY "), "COPY needs psql: {line}");
            assert!(
                !line.starts_with("SET ") || line.starts_with("SET LOCAL "),
                "session-wide setting: {line}"
            );
        }
        assert!(BASE_SCHEMA.contains("CREATE TABLE public.users_user "));
        assert!(BASE_SCHEMA.contains("INSERT INTO public.django_migrations"));
    }
}
